package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	DeptCode string `json:"dept_code"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput performs basic input cleaning
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	// Limit length to prevent buffer issues
	if len(input) > 100 {
		input = input[:100]
	}
	return input
}

// validateDepartment checks if department code is in allowed list
func validateDepartment(dept string) bool {
	allowed := []string{"ENG", "HR", "FIN", "MKT", "OPS", "LEGAL", "EXEC"}
	for _, a := range allowed {
		if strings.EqualFold(a, dept) {
			return true
		}
	}
	return false
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	// Parse form data from POST body
	if err := r.ParseForm(); err != nil {
		http.Error(w, "Bad request", 400)
		return
	}

	nameQuery := sanitizeInput(r.FormValue("name"))
	deptFilter := sanitizeInput(r.FormValue("department"))

	if nameQuery == "" {
		http.Error(w, "Name parameter required", 400)
		return
	}

	// Build query with department filter
	var query string
	if deptFilter != "" && validateDepartment(deptFilter) {
		query = fmt.Sprintf(
			"SELECT id, name, email, dept_code FROM employees WHERE dept_code = '%s' AND name ILIKE '%%%s%%'",
			deptFilter, nameQuery,
		)
	} else {
		// No department filter - search all
		query = fmt.Sprintf(
			"SELECT id, name, email, dept_code FROM employees WHERE name ILIKE '%%%s%%'",
			nameQuery,
		)
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var r SearchResult
		if err := rows.Scan(&r.ID, &r.Name, &r.Email, &r.DeptCode); err != nil {
			continue
		}
		results = append(results, r)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
